const wanted = $('Read the Price Sheet').all().map(i => i.json);
const live = new Map();
for (const p of $input.all()) {
  for (const v of (p.json.variants || [])) live.set(String(v.id), { price: Number(v.price), title: (p.json.title || '') + ' / ' + (v.title || '') });
}
const out = [];
for (const row of wanted) {
  const id = String(row.variantId || '').trim();
  const next = Number(row.newPrice);
  const cur = live.get(id);
  if (!id || !cur || !Number.isFinite(next) || next <= 0) continue;
  if (next === cur.price) continue;
  const pctChange = Math.round(((next - cur.price) / cur.price) * 1000) / 10;
  out.push({ json: { variantId: id, title: cur.title, currentPrice: cur.price, newPrice: next, pctChange, absPct: Math.abs(pctChange) } });
}
return out;
